// UsdGeomImageable — visibility and purpose.
// Reference: pxr/usd/usdGeom/imageable.h

import type { TimeCode as UsdTimeCode } from 'typescript-usd/usd'
import {_getUsdResolveInfoResult} from 'typescript-usd/usd/_internal'
import {VisibilityAPI} from './visibilityAPI.ts'
import {TfDiagnosticMgr,TfDiagnosticType,Error as TfError} from 'typescript-usd/tf'
import { SchemaBase } from 'typescript-usd/usd'
import { sdfChangeBlock } from 'typescript-usd/sdf'
import type { BBox3d as GfBBox3d } from 'typescript-usd/gf'
import { attrVal, asToken } from './valueUtils.ts'

export type Visibility = 'inherited' | 'invisible'
export type Purpose = 'default' | 'render' | 'proxy' | 'guide'

export const PURPOSE_TOKENS: readonly Purpose[] = ['default', 'render', 'proxy', 'guide']

// UsdGeomImageable::PurposeInfo (imageable.h:383-413). An empty purpose is the
// unset value (operator bool, imageable.h:398).
export interface PurposeInfo {
  purpose: string
  isInheritable: boolean
}

// PurposeInfo::GetInheritablePurpose (imageable.h:409-412).
export function getInheritablePurpose(info: PurposeInfo): string {
  return info.isInheritable ? info.purpose : ''
}

// The bound queries below construct a UsdGeomBBoxCache (imageable.cpp:547-605);
// bboxCache.ts registers its class here at module load because it imports this
// module's subclasses.
interface BBoxCacheLike {
  computeWorldBound(prim: Prim): GfBBox3d
  computeLocalBound(prim: Prim): GfBBox3d
  computeUntransformedBound(prim: Prim): GfBBox3d
}
type BBoxCacheCtor = new (
  time: number | UsdTimeCode | undefined, includedPurposes: string[]) => BBoxCacheLike
let bboxCacheCtor: BBoxCacheCtor | undefined
export function _registerBBoxCache(ctor: BBoxCacheCtor): void { bboxCacheCtor = ctor }

// _MakePurposeVector (imageable.cpp:530-545).
function makePurposeVector(purposes: readonly (string | undefined)[]): string[] {
  return purposes.filter((purpose): purpose is string => !!purpose)
}

// _ComputeAuthoredPurpose (imageable.cpp:350-364): only a valid (imageable)
// prim with an authored purpose contributes.
function computeAuthoredPurpose(prim: Prim): string {
  if (prim.isA('Imageable')) {
    const purposeAttr = prim.getAttr('purpose')
    if (purposeAttr?.hasAuthoredValue()) return asToken(purposeAttr.getValue(), '')
  }
  return ''
}

// _ComputeFallbackPurpose (imageable.cpp:366-379).
function computeFallbackPurpose(prim: Prim): string {
  if (prim.isA('Imageable')) return asToken(attrVal(prim, 'purpose'), 'default')
  return 'default'
}

// _ComputeInheritableAncestorPurpose (imageable.cpp:381-398).
function computeInheritableAncestorPurpose(prim: Prim): string {
  const stage = prim.getStage()
  let parent = parentPath(prim.path)
  while (parent) {
    const parentPrim = stage.getPrim(parent)
    if (!parentPrim) break
    const purpose = computeAuthoredPurpose(parentPrim)
    if (purpose) return purpose
    parent = parentPath(parent)
  }
  return ''
}

function parentPath(path: string): string | null {
  if (path === '/' || !path.startsWith('/')) return null
  const idx = path.lastIndexOf('/')
  return idx === 0 ? '/' : path.slice(0, idx)
}

// imageable.cpp:179-190,230-235 reads TfToken. Scalar JS strings need the
// winning source's Sdf type to distinguish token from string, independently of
// the schema type returned by UsdAttribute::GetTypeName (stage.cpp:6697-6774).
function tokenValue(attr:Attribute,time?:number):string|undefined {
  const result=_getUsdResolveInfoResult(attr.getResolveInfo(time??'default'))
  const heldType=result.layer&&result.specPath?result.layer.getField(result.specPath,'typeName'):result.typeName
  // The USDA reader retains variability alongside the authored type spelling.
  const sourceType=typeof heldType==='string'?heldType.replace(/^(?:uniform|varying)\s+/,''):heldType
  if(result.source!=='fallback'&&sourceType!=='token')return undefined
  const value=time===undefined?attr.getValue():attr.getValueAtTime(time)
  return typeof value==='string'?value:undefined
}

